def verifier(assign):
    from fractions import Fraction
    import math

    # Helper
    def gcd(a,b):
        while b:
            a,b = b, a%b
        return a
    def lcm(a,b):
        return a // gcd(a,b) * b
    def to_frac(val):
        if isinstance(val, Fraction):
            return val
        if isinstance(val, int):
            return Fraction(val,1)
        if isinstance(val, float):
            # Avoid float; but convert cautiously
            return Fraction(val).limit_denominator()
        # Assume string like 'num/den' or integer
        try:
            return Fraction(val)
        except Exception:
            return None

    # Extract placeholders
    r0 = assign.get('r0')
    a0 = assign.get('a0')
    a1 = assign.get('a1')
    a2 = assign.get('a2')
    b0 = assign.get('b0')
    b1 = assign.get('b1')
    S = to_frac(assign.get('S'))
    T = assign.get('T')
    ratio_r = to_frac(assign.get('ratio_r'))

    # Internal parameters for recomputation
    p = assign.get('p')
    q = assign.get('q')
    a = assign.get('a')
    b = assign.get('b')
    c = assign.get('c')
    d = assign.get('d')
    U = to_frac(assign.get('U'))

    # Basic validation
    if None in [r0,a0,a1,a2,b0,b1,S,T,ratio_r,p,q,a,b,c,d,U]:
        # Missing data
        return (False, None)
    if not isinstance(r0, int) or not isinstance(a0, int) or not isinstance(a1, int) or not isinstance(a2, int) or not isinstance(b0, int) or not isinstance(b1, int) or not isinstance(T, int):
        return (False, None)
    if S is None or ratio_r is None or U is None:
        return (False, None)

    # Reconstruct s,t,x,y
    s = Fraction(p, q)
    t = (a*s + b) / (c*s + d)
    x = (Fraction(1,1) - s*s) / 2
    y = (Fraction(1,1) - t*t) / 2

    # Domain checks
    if not (Fraction(0,1) < s < Fraction(1,1)):
        return (False, None)
    if not (Fraction(0,1) < t < Fraction(1,1)):
        return (False, None)
    if not (Fraction(0,1) < x < Fraction(1,2)):
        return (False, None)
    if not (Fraction(0,1) < y < Fraction(1,2)):
        return (False, None)
    if a*d - b*c <= 0:
        return (False, None)
    if c*s + d == 0:
        return (False, None)

    # Check main identity using derived structure: cube-root sum equals U, and rational function equals t + t^2/2
    # Compute F(s) from provided coefficients
    denom = (b0 + b1*s)**2
    F_s = (a0 + a1*s + a2*s*s) / denom
    LHS = Fraction(r0,1) + t
    RHS = y + F_s + U
    if LHS != RHS:
        return (False, None)

    # Check the ratio constraint
    test_ratio = ((Fraction(1,1) + s) / (Fraction(1,1) + t))**2
    if test_ratio != ratio_r:
        return (False, None)

    # Difficulty enforcement
    den_x = x.denominator
    den_y = y.denominator
    k = lcm(den_x, den_y)
    if den_x < 120 or den_y < 120 or k < 2500:
        return (False, None)

    answer = f"### The final answer is: $\\boxed{{{k}}}$"
    return (True, answer)
